Here is the commit message:
nilfs2: fix out-of-range warning

clang-14 points out that v_size is always smaller than a 64KB
page size if that is configured by the CPU architecture:

fs/nilfs2/ioctl.c:63:19: error: result of comparison of constant 65536 with expression of type '__u16' (aka 'unsigned short') is always false [-Werror,-Wtautological-constant-out-of-range-compare]
        if (argv->v_size > PAGE_SIZE)
            ~~~~~~~~~~~~ ^ ~~~~~~~~~

This is ok, so just shut up that warning with a cast.

Signed-off-by: Arnd Bergmann <arnd@arndb.de>
Link: https://lore.kernel.org/r/20240328143051.1069575-7-arnd@kernel.org
Fixes: 3358b4aaa84f ("nilfs2: fix problems of memory allocation in ioctl")
Acked-by: Ryusuke Konishi <konishi.ryusuke@gmail.com>
Reviewed-by: Justin Stitt <justinstitt@google.com>
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The bug arises from a comparison between a constant value (65536) and a variable of type `__u16` (unsigned short), which is always false if the CPU architecture is configured with a page size greater than 64KB. This leads to a compiler warning about a tautological constant out-of-range comparison, indicating that the logic may not behave as intended in certain scenarios.

Here is the patch:
  */
 static int nilfs_ioctl_wrap_copy(struct the_nilfs *nilfs,
 				 struct nilfs_argv *argv, int dir,
 				 ssize_t (*dofunc)(struct the_nilfs *,
 						   __u64 *, int,
 						   void *, size_t, size_t))
 {
 	void *buf;
 	void __user *base = (void __user *)(unsigned long)argv->v_base;
 	size_t maxmembs, total, n;
 	ssize_t nr;
 	int ret, i;
 	__u64 pos, ppos;

 	if (argv->v_nmembs == 0)
 		return 0;

-	if (argv->v_size > PAGE_SIZE)
+	if ((size_t)argv->v_size > PAGE_SIZE)
 		return -EINVAL;

 	/*
 	 * Reject pairs of a start item position (argv->v_index) and a
 	 * total count (argv->v_nmembs) which leads position 'pos' to
 	 * overflow by the increment at the end of the loop.
 	 */
 	if (argv->v_index > ~(__u64)0 - argv->v_nmembs)
 		return -EINVAL;

 	buf = (void *)get_zeroed_page(GFP_NOFS);
 	if (unlikely(!buf))
 		return -ENOMEM;
 	maxmembs = PAGE_SIZE / argv->v_size;

 	ret = 0;
 	total = 0;
 	pos = argv->v_index;
 	for (i = 0; i < argv->v_nmembs; i += n) {
 		n = (argv->v_nmembs - i < maxmembs) ?
 			argv->v_nmembs - i : maxmembs;
 		if ((dir & _IOC_WRITE) &&
 		    copy_from_user(buf, base + argv->v_size * i,
 				   argv->v_size * n)) {
 			ret = -EFAULT;
 			break;
 		}
 		ppos = pos;
 		nr = dofunc(nilfs, &pos, argv->v_flags, buf, argv->v_size,
 			       n);
 		if (nr < 0) {
 			ret = nr;
 			break;
 		}
 		if ((dir & _IOC_READ) &&
 		    copy_to_user(base + argv->v_size * i, buf,
 				 argv->v_size * nr)) {
 			ret = -EFAULT;
 			break;
 		}
 		total += nr;
 		if ((size_t)nr < n)
 			break;
 		if (pos == ppos)
 			pos += n;
 	}
 	argv->v_nmembs = total;

 	free_pages((unsigned long)buf, 0);
 	return ret;
 }



